const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '从小到大：1/3 < 1/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.12;
    var x1 = W * 0.88;
    var y = H * 0.58;
    var unit = x1 - x0;
    var xThird = x0 + unit / 3;
    var xHalf = x0 + unit / 2;
    var tickHalf = Math.max(4, Math.min(10, H * 0.035));
    var arrowLen = Math.max(10, Math.min(18, W * 0.04));
    var arrowHalf = Math.max(4, Math.min(8, H * 0.025));
    var dotR = Math.max(2, Math.min(5, W * 0.012, H * 0.012));
    var labelY = y + tickHalf + 8;
    var halfLabelY = labelY;
    if (xHalf - xThird < 48) {
      halfLabelY = Math.min(H - 6, labelY + 22);
    }
    var captionY = H * 0.16;
    var axisCommands = [['M', x0, y], ['L', x1, y]];
    var tickCommands = [];
    var xs = [x0, xThird, xHalf, x1];
    for (var i = 0; i < xs.length; i++) {
      tickCommands.push(['M', xs[i], y - tickHalf]);
      tickCommands.push(['L', xs[i], y + tickHalf]);
    }
    var arrowCommands = [
      ['M', x1 - arrowLen, y - arrowHalf],
      ['L', x1, y],
      ['L', x1 - arrowLen, y + arrowHalf]
    ];
    var dotThird = visualSdk.circle(xThird, y, dotR);
    var dotHalf = visualSdk.circle(xHalf, y, dotR);
    return {
      schemaVersion: 1,
      sceneId: 'number-line-fractions',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axisCommands },
        { id: 'ticks', commands: tickCommands },
        { id: 'arrow', commands: arrowCommands },
        { id: 'dot-third', commands: dotThird },
        { id: 'dot-half', commands: dotHalf }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'arrow', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'dot-third', fill: '#c0392b' },
          { type: 'path', pathId: 'dot-half', fill: '#c0392b' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0, y: labelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: xThird, y: labelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: xHalf, y: halfLabelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: x1, y: labelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: W / 2, y: captionY }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
